{
  "name": "agent-os",
  "version": "1.0.0",
  "description": "A tiny, self-hostable operating system for autonomous agents: one kernel that routes each task to the right capability by KIND, runs work in cycles, and records everything — zero dependencies, $0 to run, bring your own models.",
  "license": "MIT",
  "type": "commonjs",
  "scripts": {
    "test": "node examples/demo.cjs >/dev/null && echo ok",
    "check": "node --check lib/router.cjs && node --check lib/kernel.cjs && node --check lib/store.cjs && node --check lib/adapters.cjs && node --check lib/budget.cjs && node --check lib/catalog.cjs && node --check bin/agent-os.cjs && node --check examples/demo.cjs && echo ok"
  },
  "keywords": [
    "autonomous-agents",
    "agent-framework",
    "llm-routing",
    "by-kind",
    "agent-kernel",
    "continuity",
    "byo-models",
    "zero-dependencies",
    "self-hosted"
  ],
  "engines": {
    "node": ">=18"
  },
  "dependencies": {},
  "devDependencies": {},
  "bin": {
    "agent-os": "bin/agent-os.cjs"
  }
}

#!/usr/bin/env node
'use strict';
/**
 * agent-os — CLI for the Agent OS kernel.
 *
 *   agent-os init             scaffold agent-os.config.json + .env.example (never overwrites)
 *   agent-os run "<goal>"     run the kernel on a goal with the $0 echo adapter, print the trace
 *   agent-os ledger           print the scoreboard from ./.agent-os
 *   agent-os --help
 */

const fs = require('fs');
const path = require('path');
const { createRouter } = require('../lib/router.cjs');
const { echoAdapter } = require('../lib/adapters.cjs');
const { createBudget } = require('../lib/budget.cjs');
const { createStore } = require('../lib/store.cjs');
const { createKernel } = require('../lib/kernel.cjs');
const { createCatalog } = require('../lib/catalog.cjs');

const HOME = process.env.AGENT_OS_HOME || path.join(process.cwd(), '.agent-os');

function buildKernel() {
  const router = createRouter({
    seats: [{ name: 'echo', kinds: '*', act: echoAdapter() }],
    defaultSeat: 'echo',
  });
  const store = createStore(HOME);
  const budget = createBudget();
  const review = ({ out }) => ({ ok: typeof out === 'string' && out.length > 0 });
  return { kernel: createKernel({ router, store, budget, review }), store };
}

function usage() {
  process.stdout.write([
    'agent-os — a composable kernel for autonomous agents',
    '',
    'usage:',
    '  agent-os init            scaffold config (agent-os.config.json + .env.example)',
    '  agent-os run "<goal>"    run the kernel on a goal ($0 echo adapter, no key)',
    '  agent-os ledger          print the scoreboard from ./.agent-os',
    '  agent-os packs [kind]    list capabilities in the registry (optionally by kind)',
    '',
  ].join('\n') + '\n');
}

function init() {
  const cfgPath = path.join(process.cwd(), 'agent-os.config.json');
  const envPath = path.join(process.cwd(), '.env.example');
  const cfg = {
    seats: [{ name: 'echo', kinds: '*' }],
    defaultSeat: 'echo',
    maxCycles: 4,
    note: 'Register real models in code with bringYourOwn(fn, kinds, name); the echo seat runs $0.',
  };
  let wrote = 0;
  if (fs.existsSync(cfgPath)) process.stdout.write('agent-os.config.json already exists — left unchanged\n');
  else { fs.writeFileSync(cfgPath, JSON.stringify(cfg, null, 2) + '\n'); wrote++; process.stdout.write('wrote agent-os.config.json\n'); }
  if (fs.existsSync(envPath)) process.stdout.write('.env.example already exists — left unchanged\n');
  else { fs.writeFileSync(envPath, '# AGENT_OS_HOME=./.agent-os   # where memory.jsonl + ledger.jsonl live\n'); wrote++; process.stdout.write('wrote .env.example\n'); }
  process.stdout.write(wrote ? 'init done.\n' : 'nothing to do.\n');
}

async function run(goal) {
  if (!goal) { process.stderr.write('usage: agent-os run "<goal>"\n'); process.exit(2); }
  const { kernel } = buildKernel();
  const result = await kernel.run(goal, { maxCycles: 4 });
  process.stdout.write(`\ngoal: ${result.goal}\n\n`);
  for (const c of result.cycles) {
    const body = c.outcome === 'ok' ? String(c.out).replace(/\s+/g, ' ').slice(0, 72) : `ERROR ${c.error}`;
    process.stdout.write(`cycle ${c.cycle} · kind=${c.kind} · seat=${c.seat || '-'} → ${body}\n`);
  }
  const s = result.scoreboard;
  process.stdout.write(`\nscoreboard: ${s.cycles} cycles · successRate=${s.successRate}\n`);
  process.stdout.write(`continuity:\n${result.continuity.split('\n').map((l) => '  ' + l).join('\n')}\n`);
}

function ledger() {
  const store = createStore(HOME);
  const s = store.scoreboard();
  process.stdout.write(`scoreboard (${HOME}):\n`);
  process.stdout.write(`  cycles: ${s.cycles} · successRate: ${s.successRate}\n`);
  process.stdout.write(`  byKind: ${JSON.stringify(s.byKind)}\n`);
  process.stdout.write(`  byOutcome: ${JSON.stringify(s.byOutcome)}\n`);
}

function packs(kindFilter) {
  const cat = createCatalog();
  const list = kindFilter ? cat.byKind(kindFilter) : cat.all();
  if (!list.length) {
    process.stdout.write(`no capabilities of kind "${kindFilter}". known kinds: ${cat.kinds().join(', ')}\n`);
    return;
  }
  const header = kindFilter ? `capabilities · kind=${kindFilter}` : `capabilities · ${cat.engines().length} engines + ${cat.packs().length} packs`;
  process.stdout.write(`\n${header}\n\n`);
  for (const p of list) {
    process.stdout.write(`  [${p.type === 'engine' ? 'engine' : ' pack '}] ${String(p.kind).padEnd(13)} ${p.name}\n            ${p.summary}\n`);
  }
  if (!kindFilter) process.stdout.write(`\nkinds: ${cat.kinds().join(', ')}\n`);
  process.stdout.write('\n');
}

async function main() {
  const [cmd, ...rest] = process.argv.slice(2);
  if (!cmd || cmd === '--help' || cmd === '-h') return usage();
  if (cmd === 'init') return init();
  if (cmd === 'run') return run(rest.join(' ').trim());
  if (cmd === 'ledger') return ledger();
  if (cmd === 'packs') return packs(rest.join(' ').trim() || null);
  process.stderr.write(`unknown command: ${cmd}\n`);
  usage();
  process.exit(2);
}

main().catch((e) => { process.stderr.write(`agent-os: ${e && e.message || e}\n`); process.exit(1); });
